<template><CoopTaskSheet :show="show" title="发布线索" :busy="busy || uploading" :inactive="picker" full @close="$emit('close')"><view class="coop-form-section"><view class="coop-section-title">客户资料</view><view class="coop-form-row"><text>客户称呼</text><input v-model="form.customer_name" maxlength="80" placeholder="例如：刘先生" :disabled="busy" /></view><view class="coop-form-row"><text>联系电话</text><input v-model="form.mobile" type="number" maxlength="20" placeholder="客户手机号" :disabled="busy" /></view><view class="coop-form-column"><text>客户所在地区</text><CoopRegionFields v-model="region" :disabled="busy" /></view></view><view class="coop-form-section"><view class="coop-section-title">客户想找什么</view><view class="coop-type-switch"><view v-for="item in types" :key="item.value" :class="{ active: form.business_type === item.value }" @tap="!busy && (form.business_type = item.value)">{{ item.label }}<text v-if="form.business_type === item.value"> ✓</text></view></view><view class="coop-search-trigger" @tap="!busy && (picker = true)"><u-icon name="search" color="#9ba3ad" size="17" /><text>搜索客户需要的型号，可多选</text></view><view class="coop-chosen-models"><view v-for="model in models" :key="String(model.id)" @tap="removeModel(model.id)"><text>{{ model.title }}</text><u-icon name="close" size="11" color="#929ca7" /></view></view></view><view class="coop-form-section"><view class="coop-section-title">补充沟通截图<text>选填</text></view><CoopAttachmentUpload v-model="form.attachments" :disabled="busy" @pending="uploading = $event" /><view class="coop-fold-title" @tap="remarkOpen = !remarkOpen">补充备注<u-icon :name="remarkOpen ? 'arrow-up' : 'arrow-down'" size="12" color="#929ba6" /></view><u-textarea v-if="remarkOpen" v-model="form.remark" :disabled="busy" :maxlength="2000" placeholder="预算、成色或到店时间等，选填" /></view><view class="coop-consent" @tap="!busy && (form.consent = !form.consent)"><u-icon :name="form.consent ? 'checkmark-circle-fill' : 'circle'" size="19" :color="form.consent ? 'var(--primary-color, #d93833)' : '#bcc4ce'" /><text>已向客户说明，会将必要联系方式与需求交给所选门店跟进。</text></view><view v-if="localError || error" class="coop-inline-error coop-form-error">{{ localError || error }}</view><template #footer><u-button type="primary" shape="circle" text="下一步，选交付门店" :loading="busy || uploading" loading-text="正在保存" :disabled="busy || uploading" @click="submit" /></template></CoopTaskSheet><CoopModelSearchPicker :show="picker" v-model="models" @close="picker = false" /></template>
<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { coopRequestId, type CoopRow } from '../../api/cooperation'
import CoopTaskSheet from './CoopTaskSheet.vue'
import CoopRegionFields from './CoopRegionFields.vue'
import CoopAttachmentUpload from './CoopAttachmentUpload.vue'
import CoopModelSearchPicker from './CoopModelSearchPicker.vue'
defineProps<{ show: boolean; busy?: boolean; error?: string }>()
const emit = defineEmits<{ (event: 'close'): void; (event: 'submit', data: CoopRow): void }>()
const initial = () => ({ request_id: coopRequestId(), customer_name: '', mobile: '', province_id: 0, city_id: 0, district_id: 0, region_text: '', business_type: 'purchase', attachments: [] as string[], remark: '', consent: false })
const form = reactive(initial()), models = ref<CoopRow[]>([]), picker = ref(false), uploading = ref(false), remarkOpen = ref(false), localError = ref('')
const region = computed({ get: () => form, set: value => Object.assign(form, value) })
const types = [{ value: 'purchase', label: '购买' }, { value: 'rent', label: '租机' }, { value: 'exchange', label: '置换' }]
function removeModel(id: string) { models.value = models.value.filter(item => String(item.id) !== String(id)) }
function submit() { localError.value = ''; if (!form.customer_name.trim()) { localError.value = '请填写客户称呼'; return }; if (!/^1\d{10}$/.test(form.mobile.trim())) { localError.value = '请填写有效的客户手机号'; return }; if (!form.district_id) { localError.value = '请选择客户所在省、市、区县'; return }; if (!models.value.length) { localError.value = '请至少选择一个意向型号'; return }; if (!form.consent) { localError.value = '请先向客户说明联系方式用途并确认'; return }; emit('submit', { ...form, mobile: form.mobile.trim(), customer_name: form.customer_name.trim(), model_ids: models.value.map(item => String(item.id)) }) }
function clear() { Object.assign(form, initial()); models.value = []; localError.value = ''; picker.value = false; remarkOpen.value = false }
defineExpose({ clear })
</script>
